-- V1.9.6 — Suivi collectif individualisé (26 November 2026). A coach follows a group without treating every athlete the same way: a private
-- group of their own links, one block prepared from a template, a variant per athlete, the list of who will receive which version BEFORE
-- the send, a send that treats every recipient separately (success or refusal, each with its reason), a resumption of the incomplete sends
-- that never repeats one already made, and a review of the group with the next action per athlete and the coach's follow-up load.
-- Behind the server flag screens.coach_groups (absent = closed). It REUSES what exists and copies nothing private:
--   the sharing link (public.coach_links: scope, pause of capacity, revocation) decides every send and every read, for each recipient, at
--   that moment: a paused link (beyond the places of the offer, private.titan_coach_link_active) or a revoked one receives nothing;
--   a recipient's version is an ordinary V1.9.4 programme (private.titan_coach_plans, sent) whose sessions are ordinary proposals
--   (public.coach_assignments): the athlete answers it in their own space exactly as before and sees neither the group nor anyone else;
--   the next actions of the review are read through the V1.9.1 row (private.titan_coach_followup_row, the link's contract applies) and the
--   group review shows only counts and states: the personal data stay in the individual views, checked against each link.
-- New:
--   private.titan_coach_groups / _group_members  a group of the coach's own links, private to the coach (never shown to an athlete);
--   private.titan_coach_dispatches  one block to send to a group: the template version it comes from (frozen), the start date, a revision;
--   private.titan_coach_dispatch_recipients  one row per athlete of the block: their variant (start shifted by whole weeks, a weekday moved
--                     to another, sessions moved or left out), whether the coach excluded them, the outcome of the last attempt (pending,
--                     sent, failed with its reason) and the programme created for them (one at most: a resumption never creates a second);
--   private.titan_coach_dispatch_sends  one entry per send (op_id): its per-recipient results, so a replayed call writes nothing.
-- The send is applied with the preview's key: if a variant, a member or a link changed since the preview, it is refused (COACH_CONFLICT) and
-- the coach previews again. Each recipient is sent in its own sub-transaction: one refusal never stops or undoes the others.
-- Deleting a group deletes the group, its members and its blocks (the coach's organisation); the programmes the athletes received stay
-- theirs, unchanged. A link that ends leaves every group and every pending send (it is reported as « suivi arrêté », without a name).
-- No action writes public.training_logs, a note or a check-in. No XP, no credit, no notification. Additive. The caller owns the
-- transaction: never BEGIN/COMMIT here.
-- Rollback: drop function public.titan_coach_group_v1(text, jsonb), private.titan_coach_group_measure(),
-- private.titan_coach_group_variant(jsonb, jsonb, integer), private.titan_coach_dispatch_row(private.titan_coach_dispatches, boolean),
-- private.titan_coach_group_next(public.coach_links); re-apply private.titan_export_extras_v1 of 20261205090000; drop table private.titan_coach_dispatch_sends,
-- private.titan_coach_dispatch_recipients, private.titan_coach_dispatches, private.titan_coach_group_members, private.titan_coach_groups.

create table if not exists private.titan_coach_groups (
  id uuid primary key default gen_random_uuid(),
  coach_id uuid not null references auth.users(id) on delete cascade,
  title text not null check (char_length(title) between 1 and 60),
  revision integer not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists titan_coach_groups_coach_idx on private.titan_coach_groups (coach_id, updated_at desc);
create table if not exists private.titan_coach_group_members (
  group_id uuid not null references private.titan_coach_groups(id) on delete cascade,
  link_id uuid not null references public.coach_links(id) on delete cascade,
  added_at timestamptz not null default now(),
  primary key (group_id, link_id)
);
create index if not exists titan_coach_group_members_link_idx on private.titan_coach_group_members (link_id);
create table if not exists private.titan_coach_dispatches (
  id uuid primary key default gen_random_uuid(),
  group_id uuid not null references private.titan_coach_groups(id) on delete cascade,
  coach_id uuid not null references auth.users(id) on delete cascade,
  program_id uuid references private.titan_coach_programs(id) on delete set null,
  program_version integer,
  title text not null check (char_length(title) between 1 and 100),
  goals jsonb not null default '[]'::jsonb check (jsonb_typeof(goals) = 'array' and jsonb_array_length(goals) <= 5),
  weeks smallint not null check (weeks between 1 and 12),
  sessions jsonb not null check (jsonb_typeof(sessions) = 'array' and jsonb_array_length(sessions) between 1 and 60),
  start_date date not null check (extract(isodow from start_date) = 1),
  revision integer not null default 1,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  first_sent_at timestamptz,
  completed_at timestamptz
);
create index if not exists titan_coach_dispatches_group_idx on private.titan_coach_dispatches (group_id, created_at desc);
create table if not exists private.titan_coach_dispatch_recipients (
  dispatch_id uuid not null references private.titan_coach_dispatches(id) on delete cascade,
  link_id uuid not null references public.coach_links(id) on delete cascade,
  variant jsonb not null default '{}'::jsonb check (jsonb_typeof(variant) = 'object'),
  excluded boolean not null default false,
  status text not null default 'pending' check (status in ('pending', 'sent', 'failed')),
  error text check (error is null or error ~ '^[A-Z_]{3,40}$'),
  attempts integer not null default 0,
  plan_id uuid references private.titan_coach_plans(id) on delete set null,
  last_attempt_at timestamptz,
  sent_at timestamptz,
  primary key (dispatch_id, link_id),
  check ((status = 'sent') = (sent_at is not null)),
  check ((status = 'failed') = (error is not null))
);
create unique index if not exists titan_coach_dispatch_recipients_plan on private.titan_coach_dispatch_recipients (plan_id) where plan_id is not null;
create table if not exists private.titan_coach_dispatch_sends (
  dispatch_id uuid not null references private.titan_coach_dispatches(id) on delete cascade,
  op_id uuid not null,
  results jsonb not null check (jsonb_typeof(results) = 'array'),
  created_at timestamptz not null default now(),
  primary key (dispatch_id, op_id)
);
alter table private.titan_coach_groups enable row level security;
alter table private.titan_coach_group_members enable row level security;
alter table private.titan_coach_dispatches enable row level security;
alter table private.titan_coach_dispatch_recipients enable row level security;
alter table private.titan_coach_dispatch_sends enable row level security;
revoke all on private.titan_coach_groups, private.titan_coach_group_members, private.titan_coach_dispatches, private.titan_coach_dispatch_recipients,
  private.titan_coach_dispatch_sends from public, anon, authenticated;

-- A recipient's version of the block: the template's sessions, with the variant applied, checked like any programme of V1.9.4.
--   shift_weeks 0..4  the block starts that many weeks later for this athlete (the weeks keep their numbers);
--   day_map {"2":3}  every session of a weekday moves to another weekday of the same week (Tuesday → Wednesday);
--   moves [{key, week, day}]  one session moves (after day_map);  skip [key]  sessions left out for this athlete.
-- Returns {shift_weeks, sessions, changes} or raises BAD_VARIANT. At least one session must remain.
create or replace function private.titan_coach_group_variant(p_sessions jsonb, p_variant jsonb, p_weeks integer)
returns jsonb language plpgsql volatile security definer set search_path = ''
as $function$
declare v_shift integer := 0; v_map jsonb := '{}'::jsonb; v_skip text[] := '{}'; v_moves jsonb := '[]'::jsonb; v_out jsonb := '[]'::jsonb; e jsonb; m jsonb;
  v_k text; v_d integer;
begin
  if p_variant is null or jsonb_typeof(p_variant) <> 'object' then raise exception 'BAD_VARIANT' using errcode = '22023'; end if;
  if exists (select 1 from jsonb_object_keys(p_variant) k where k not in ('shift_weeks', 'day_map', 'moves', 'skip')) then raise exception 'BAD_VARIANT' using errcode = '22023'; end if;
  begin
    v_shift := coalesce(nullif(p_variant->>'shift_weeks', '')::integer, 0);
    if p_variant ? 'day_map' then v_map := p_variant->'day_map'; end if;
    if p_variant ? 'moves' then v_moves := p_variant->'moves'; end if;
    if p_variant ? 'skip' then select coalesce(array_agg(x #>> '{}'), '{}') into v_skip from jsonb_array_elements(p_variant->'skip') x; end if;
  exception when others then raise exception 'BAD_VARIANT' using errcode = '22023'; end;
  if v_shift < 0 or v_shift > 4 or jsonb_typeof(v_map) <> 'object' or jsonb_typeof(v_moves) <> 'array' or jsonb_array_length(v_moves) > 60 or cardinality(v_skip) > 60 then
    raise exception 'BAD_VARIANT' using errcode = '22023';
  end if;
  for v_k in select jsonb_object_keys(v_map) loop
    if v_k !~ '^[1-7]$' or coalesce(v_map->>v_k, '') !~ '^[1-7]$' then raise exception 'BAD_VARIANT' using errcode = '22023'; end if;
  end loop;
  if exists (select 1 from unnest(v_skip) u(k) where not exists (select 1 from jsonb_array_elements(p_sessions) z(x) where z.x->>'key' = u.k)) then raise exception 'BAD_VARIANT' using errcode = '22023'; end if;
  for e in select x from jsonb_array_elements(p_sessions) x loop
    if (e->>'key') = any(v_skip) then continue; end if;
    v_d := coalesce((v_map->>(e->>'day'))::integer, (e->>'day')::integer);
    e := jsonb_set(e, '{day}', to_jsonb(v_d));
    v_out := v_out || jsonb_build_array(e);
  end loop;
  for m in select x from jsonb_array_elements(v_moves) x loop
    if jsonb_typeof(m) <> 'object' or not exists (select 1 from jsonb_array_elements(v_out) z(x) where z.x->>'key' = m->>'key') then raise exception 'BAD_VARIANT' using errcode = '22023'; end if;
    begin
      select jsonb_agg(case when z.x->>'key' = m->>'key' then z.x || jsonb_build_object('week', (m->>'week')::integer, 'day', (m->>'day')::integer) else z.x end) into v_out
        from jsonb_array_elements(v_out) z(x);
    exception when others then raise exception 'BAD_VARIANT' using errcode = '22023'; end;
  end loop;
  if jsonb_array_length(v_out) = 0 then raise exception 'BAD_VARIANT' using errcode = '22023'; end if;
  begin
    v_out := private.titan_coach_program_sessions(v_out, p_weeks);
  exception when others then raise exception 'BAD_VARIANT' using errcode = '22023'; end;
  return jsonb_build_object('shift_weeks', v_shift, 'sessions', v_out, 'changes', private.titan_coach_plan_changes(p_sessions, v_out));
end;
$function$;
revoke all on function private.titan_coach_group_variant(jsonb, jsonb, integer) from public, anon, authenticated;

-- The next action for one athlete of a group, read through the V1.9.1 row of their proposals (the link's contract applies) and their
-- programmes: counts and states only, never a measure, a note or a check-in. The coach opens the individual view to see more.
create or replace function private.titan_coach_group_next(l public.coach_links)
returns jsonb language plpgsql stable security definer set search_path = ''
as $function$
declare v_rows jsonb; v_plan private.titan_coach_plans%rowtype; v_today date := (now() at time zone 'Europe/Paris')::date; v_c jsonb; v_next text;
  v_report text; v_reports boolean := private.titan_flag_on('screens.coach_cycle_report');
begin
  select coalesce(jsonb_agg(private.titan_coach_followup_row(a, l, 'coach') - 'history' - 'candidates' - 'accepted_version' - 'linked' - 'instructions' - 'discuss_note'), '[]'::jsonb) into v_rows
    from public.coach_assignments a
   where a.link_id = l.id and a.status <> 'cancelled'
     and (a.status in ('proposed', 'declined') or a.pending_change is not null or a.planned_date >= v_today - 60 or a.moved_date >= v_today - 60);
  select * into v_plan from private.titan_coach_plans p where p.link_id = l.id and p.state in ('sent', 'closed') order by p.start_date desc, p.created_at desc limit 1;
  if v_plan.id is not null and v_reports then
    select r.state || case when r.version >= 1 then ':published' else '' end into v_report from private.titan_coach_cycle_reports r where r.plan_id = v_plan.id;
  end if;
  v_c := jsonb_build_object(
    'to_discuss', (select count(*) from jsonb_array_elements(v_rows) e where e->>'state' = 'to_discuss'),
    'awaiting', (select count(*) from jsonb_array_elements(v_rows) e where e->>'state' = 'awaiting'),
    'reproposed', (select count(*) from jsonb_array_elements(v_rows) e where e->>'state' = 'reproposed'),
    'gaps', (select count(*) from jsonb_array_elements(v_rows) e where e->>'coach_next' = 'gap' and e->>'state' <> 'to_discuss' and (e->>'seen')::boolean is not true),
    'overdue', (select count(*) from jsonb_array_elements(v_rows) e where e->>'state' = 'overdue'),
    'to_match', (select count(*) from jsonb_array_elements(v_rows) e where e->>'state' = 'to_match'),
    'declined', (select count(*) from jsonb_array_elements(v_rows) e where e->>'state' = 'declined'),
    'linked', (select count(*) from jsonb_array_elements(v_rows) e where e->>'state' = 'linked'));
  v_next := case
    when (v_c->>'to_discuss')::integer > 0 then 'discuss'
    when (v_c->>'gaps')::integer > 0 then 'feedback'
    when v_plan.id is not null and v_reports and (v_plan.state = 'closed' or v_plan.start_date + v_plan.weeks * 7 - 1 < v_today) and coalesce(v_report, '') not like '%published' then 'report'
    when (v_c->>'awaiting')::integer > 0 or (v_c->>'reproposed')::integer > 0 then 'wait_answer'
    when v_plan.id is null or v_plan.state = 'closed' or v_plan.start_date + v_plan.weeks * 7 - 1 < v_today then 'plan'
    else 'none' end;
  return jsonb_build_object('next', v_next, 'counts', v_c,
    'cases', (v_c->>'to_discuss')::integer + (v_c->>'gaps')::integer + case when v_next = 'report' then 1 else 0 end,
    'plan', case when v_plan.id is null then null else jsonb_build_object('id', v_plan.id, 'title', v_plan.title, 'state', v_plan.state, 'weeks', v_plan.weeks,
      'start_date', v_plan.start_date, 'end_date', v_plan.start_date + v_plan.weeks * 7 - 1,
      'current_week', case when v_today between v_plan.start_date and v_plan.start_date + v_plan.weeks * 7 - 1 then (v_today - v_plan.start_date) / 7 + 1 else null end,
      'sessions', (select count(*) from public.coach_assignments a where a.plan_id = v_plan.id and a.status <> 'cancelled'),
      'accepted', (select count(*) from public.coach_assignments a where a.plan_id = v_plan.id and a.status in ('accepted', 'completed')),
      'report', v_report) end);
end;
$function$;
revoke all on function private.titan_coach_group_next(public.coach_links) from public, anon, authenticated;

-- A block as the coach sees it: per recipient, the link's state now (a revoked link loses its name), the variant, the version they would
-- receive (dates of every session, what differs from the common template), the predicted outcome and the outcome of the last attempt.
-- The preview key covers the block's revision, every recipient's variant, exclusion and status, and every link's state.
create or replace function private.titan_coach_dispatch_row(d private.titan_coach_dispatches, p_detail boolean default true)
returns jsonb language plpgsql stable security definer set search_path = ''
as $function$
declare v_today date := (now() at time zone 'Europe/Paris')::date; v_rows jsonb := '[]'::jsonb; r record; v_v jsonb; v_state text; v_predict text; v_start date;
  v_sessions jsonb; v_key text := d.revision::text;
begin
  for r in
    select x.*, l.revoked_at, l.athlete_id, p.username, (l.revoked_at is null and private.titan_coach_link_active(l.id)) active,
           (select count(*) from public.coach_assignments a where a.link_id = l.id) n_assign,
           (select count(*) from private.titan_coach_plans q where q.link_id = l.id and q.state <> 'discarded') n_plans,
           (select q.state from private.titan_coach_plans q where q.id = x.plan_id) plan_state
      from private.titan_coach_dispatch_recipients x join public.coach_links l on l.id = x.link_id left join public.profiles p on p.id = l.athlete_id
     where x.dispatch_id = d.id order by case when l.revoked_at is null then 0 else 1 end, lower(coalesce(p.username, '')), x.link_id
  loop
    v_state := case when r.revoked_at is not null then 'revoked' when r.active then 'active' else 'paused' end;
    v_v := null; v_predict := null;
    begin
      v_v := private.titan_coach_group_variant(d.sessions, r.variant, d.weeks);
    exception when others then v_predict := 'BAD_VARIANT';
    end;
    v_start := d.start_date + 7 * coalesce((v_v->>'shift_weeks')::integer, 0);
    v_predict := case
      when r.status = 'sent' then 'sent'
      when r.excluded then 'excluded'
      when r.revoked_at is not null then 'SHARING_UNAVAILABLE'
      when not r.active then 'COACH_CAPACITY_PAUSED'
      when v_predict is not null then v_predict
      when exists (select 1 from jsonb_array_elements(v_v->'sessions') e
                    where v_start + ((e->>'week')::integer - 1) * 7 + (e->>'day')::integer - 1 not between v_today and v_today + 366) then 'INVALID_PERIOD'
      when r.n_plans >= 50 then 'PLAN_LIMIT'
      when r.n_assign + jsonb_array_length(v_v->'sessions') > 500 then 'ASSIGNMENT_LIMIT'
      else 'ready' end;
    v_key := v_key || '|' || concat_ws(':', r.link_id, r.variant::text, r.excluded, r.status, v_state);
    if v_v is not null then
      select jsonb_agg(e || jsonb_build_object('planned_date', v_start + ((e->>'week')::integer - 1) * 7 + (e->>'day')::integer - 1)
               order by (e->>'week')::integer, (e->>'day')::integer, e->>'key') into v_sessions from jsonb_array_elements(v_v->'sessions') e;
    end if;
    v_rows := v_rows || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
      'link_id', r.link_id, 'name', case when r.revoked_at is null then r.username else null end, 'link_state', v_state,
      'variant', r.variant, 'excluded', r.excluded, 'individual', r.variant <> '{}'::jsonb,
      'status', r.status, 'error', r.error, 'attempts', r.attempts, 'last_attempt_at', r.last_attempt_at, 'sent_at', r.sent_at,
      'plan_id', case when r.revoked_at is null then r.plan_id else null end, 'plan_state', case when r.revoked_at is null then r.plan_state else null end,
      'predict', v_predict,
      'start_date', case when v_v is not null then v_start else null end,
      'end_date', case when v_v is not null then v_start + d.weeks * 7 - 1 else null end,
      'session_count', case when v_v is not null then jsonb_array_length(v_v->'sessions') else null end,
      'changes', case when v_v is not null then v_v->'changes' else null end,
      'sessions', case when p_detail and v_v is not null and r.revoked_at is null then v_sessions else null end)));
  end loop;
  return jsonb_build_object('id', d.id, 'group_id', d.group_id, 'title', d.title, 'goals', d.goals, 'weeks', d.weeks, 'start_date', d.start_date,
    'program', jsonb_build_object('id', d.program_id, 'version', d.program_version), 'revision', d.revision, 'today', v_today,
    'sessions', case when p_detail then d.sessions else null end, 'created_at', d.created_at, 'first_sent_at', d.first_sent_at, 'completed_at', d.completed_at,
    'recipients', v_rows,
    'counts', jsonb_build_object('recipients', jsonb_array_length(v_rows),
      'individual', (select count(*) from jsonb_array_elements(v_rows) e where (e->>'individual')::boolean and e->>'predict' <> 'excluded'),
      'ready', (select count(*) from jsonb_array_elements(v_rows) e where e->>'predict' = 'ready'),
      'blocked', (select count(*) from jsonb_array_elements(v_rows) e where e->>'predict' not in ('ready', 'sent', 'excluded')),
      'excluded', (select count(*) from jsonb_array_elements(v_rows) e where e->>'predict' = 'excluded'),
      'sent', (select count(*) from jsonb_array_elements(v_rows) e where e->>'status' = 'sent'),
      'failed', (select count(*) from jsonb_array_elements(v_rows) e where e->>'status' = 'failed' and e->>'predict' <> 'excluded')),
    'preview_key', left(md5(v_key), 20));
end;
$function$;
revoke all on function private.titan_coach_dispatch_row(private.titan_coach_dispatches, boolean) from public, anon, authenticated;

create or replace function public.titan_coach_group_v1(p_action text, p_data jsonb default '{}'::jsonb)
returns jsonb language plpgsql security definer set search_path = '' set statement_timeout = '15s'
as $function$
declare
  v_uid uuid := auth.uid(); v_today date := (now() at time zone 'Europe/Paris')::date; v_id uuid; v_group private.titan_coach_groups%rowtype;
  v_d private.titan_coach_dispatches%rowtype; v_prog private.titan_coach_programs%rowtype; v_pv private.titan_coach_program_versions%rowtype;
  v_link public.coach_links%rowtype; v_plan private.titan_coach_plans%rowtype; v_title text; v_links uuid[]; v_date date; v_row jsonb; v_op uuid;
  v_results jsonb := '[]'::jsonb; v_v jsonb; v_start date; v_err text; r record; v_n integer; v_cap integer; v_used integer; v_name text;
begin
  if v_uid is null or not exists (select 1 from public.profiles where id = v_uid and is_suspended is not true) then raise exception 'AUTH_REQUIRED' using errcode = '42501'; end if;
  if jsonb_typeof(p_data) is distinct from 'object' or octet_length(p_data::text) > 60000 then raise exception 'INVALID_INPUT' using errcode = '22023'; end if;
  if not private.titan_flag_on('screens.coach_groups') then raise exception 'FEATURE_DISABLED' using errcode = '42501'; end if;
  begin
    v_id := nullif(p_data->>'id', '')::uuid;
  exception when others then raise exception 'INVALID_INPUT' using errcode = '22023'; end;
  -- Groups are the coach's organisation: an athlete has no group, and no action here ever returns another athlete's content.
  if not exists (select 1 from public.coach_links l where l.coach_id = v_uid) then raise exception 'COACH_ONLY' using errcode = '42501'; end if;
  v_cap := private.titan_coach_capacity(v_uid);
  select count(*) into v_used from public.coach_links where coach_id = v_uid and revoked_at is null;

  -- ---- The coach's groups: members (active, paused, ended), the follow-up load, the last block.
  if p_action = 'groups' then
    return jsonb_build_object('owner', v_uid, 'today', v_today, 'capacity', v_cap, 'links_used', v_used,
      'paused', (select count(*) from public.coach_links l where l.coach_id = v_uid and l.revoked_at is null and not private.titan_coach_link_active(l.id)),
      'links', coalesce((select jsonb_agg(jsonb_build_object('link_id', l.id, 'name', p.username, 'active', private.titan_coach_link_active(l.id)) order by lower(p.username), l.id)
                           from public.coach_links l join public.profiles p on p.id = l.athlete_id where l.coach_id = v_uid and l.revoked_at is null), '[]'::jsonb),
      'groups', coalesce((select jsonb_agg(jsonb_build_object('id', g.id, 'title', g.title, 'revision', g.revision, 'updated_at', g.updated_at,
          'members', (select count(*) from private.titan_coach_group_members m join public.coach_links l on l.id = m.link_id where m.group_id = g.id and l.revoked_at is null),
          'active', (select count(*) from private.titan_coach_group_members m join public.coach_links l on l.id = m.link_id where m.group_id = g.id and l.revoked_at is null and private.titan_coach_link_active(l.id)),
          'ended', (select count(*) from private.titan_coach_group_members m join public.coach_links l on l.id = m.link_id where m.group_id = g.id and l.revoked_at is not null),
          'dispatches', (select count(*) from private.titan_coach_dispatches d where d.group_id = g.id),
          'incomplete', (select count(*) from private.titan_coach_dispatches d where d.group_id = g.id and d.first_sent_at is not null and d.completed_at is null)) order by g.updated_at desc, g.id)
        from private.titan_coach_groups g where g.coach_id = v_uid), '[]'::jsonb));
  end if;

  -- ---- One group: its members (a revoked link is « suivi arrêté », without a name), its blocks, and the review when asked.
  if p_action in ('group', 'review') then
    select * into v_group from private.titan_coach_groups where id = v_id and coach_id = v_uid;
    if not found then raise exception 'GROUP_UNAVAILABLE' using errcode = '22023'; end if;
    v_row := jsonb_build_object('id', v_group.id, 'title', v_group.title, 'revision', v_group.revision, 'today', v_today, 'capacity', v_cap, 'links_used', v_used,
      'members', coalesce((select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('link_id', l.id,
            'name', case when l.revoked_at is null then p.username else null end,
            'link_state', case when l.revoked_at is not null then 'revoked' when private.titan_coach_link_active(l.id) then 'active' else 'paused' end,
            'added_at', m.added_at,
            'review', case when p_action = 'review' and l.revoked_at is null and private.titan_coach_link_active(l.id) then private.titan_coach_group_next(l) else null end))
          order by case when l.revoked_at is null then 0 else 1 end, lower(coalesce(p.username, '')), l.id)
        from private.titan_coach_group_members m join public.coach_links l on l.id = m.link_id left join public.profiles p on p.id = l.athlete_id
       where m.group_id = v_group.id and (l.revoked_at is null or l.revoked_at > now() - interval '30 days')), '[]'::jsonb),
      'dispatches', coalesce((select jsonb_agg(jsonb_build_object('id', d.id, 'title', d.title, 'start_date', d.start_date, 'weeks', d.weeks, 'created_at', d.created_at,
            'first_sent_at', d.first_sent_at, 'completed_at', d.completed_at,
            'recipients', (select count(*) from private.titan_coach_dispatch_recipients x where x.dispatch_id = d.id),
            'sent', (select count(*) from private.titan_coach_dispatch_recipients x where x.dispatch_id = d.id and x.status = 'sent'),
            'failed', (select count(*) from private.titan_coach_dispatch_recipients x where x.dispatch_id = d.id and x.status = 'failed' and not x.excluded)) order by d.created_at desc)
        from private.titan_coach_dispatches d where d.group_id = v_group.id), '[]'::jsonb));
    if p_action = 'review' then
      -- The coach's load: the cases to handle now, the athletes with something to do, the answers awaited, and the places of the offer.
      v_row := v_row || jsonb_build_object('load', jsonb_build_object(
        'members_active', (select count(*) from jsonb_array_elements(v_row->'members') e where e->>'link_state' = 'active'),
        'members_paused', (select count(*) from jsonb_array_elements(v_row->'members') e where e->>'link_state' = 'paused'),
        'members_ended', (select count(*) from jsonb_array_elements(v_row->'members') e where e->>'link_state' = 'revoked'),
        'with_action', (select count(*) from jsonb_array_elements(v_row->'members') e where e#>>'{review,next}' in ('discuss', 'feedback', 'report', 'plan')),
        'cases', (select coalesce(sum((e#>>'{review,cases}')::integer), 0) from jsonb_array_elements(v_row->'members') e),
        'to_discuss', (select coalesce(sum((e#>>'{review,counts,to_discuss}')::integer), 0) from jsonb_array_elements(v_row->'members') e),
        'feedback', (select coalesce(sum((e#>>'{review,counts,gaps}')::integer), 0) from jsonb_array_elements(v_row->'members') e),
        'awaiting', (select coalesce(sum((e#>>'{review,counts,awaiting}')::integer), 0) from jsonb_array_elements(v_row->'members') e),
        'reports', (select count(*) from jsonb_array_elements(v_row->'members') e where e#>>'{review,next}' = 'report'),
        'capacity', v_cap, 'links_used', v_used));
    end if;
    return v_row;
  end if;

  if p_action = 'dispatch' then
    select * into v_d from private.titan_coach_dispatches where id = v_id and coach_id = v_uid;
    if not found then raise exception 'DISPATCH_UNAVAILABLE' using errcode = '22023'; end if;
    return private.titan_coach_dispatch_row(v_d, true);
  end if;

  if p_action not in ('create_group', 'edit_group', 'delete_group', 'prepare', 'variant', 'discard', 'send') then raise exception 'INVALID_ACTION' using errcode = '22023'; end if;
  perform private.titan_rate_limit(v_uid, 'coach_group', 120);

  if p_action in ('create_group', 'edit_group') then
    if p_data ? 'title' or p_action = 'create_group' then
      v_title := left(regexp_replace(btrim(coalesce(p_data->>'title', '')), '[[:cntrl:]<>]', '', 'g'), 60);
      if v_title = '' then raise exception 'BAD_TITLE' using errcode = '22023'; end if;
    end if;
    if p_data ? 'link_ids' then
      begin select coalesce(array_agg(distinct (x #>> '{}')::uuid), '{}') into v_links from jsonb_array_elements(p_data->'link_ids') x;
      exception when others then raise exception 'INVALID_INPUT' using errcode = '22023'; end;
      if cardinality(v_links) > 30 then raise exception 'GROUP_LIMIT' using errcode = '22023'; end if;
      -- Only the coach's own current links (paused ones included: they stay members and simply receive nothing while paused).
      if exists (select 1 from unnest(v_links) u where not exists (select 1 from public.coach_links l where l.id = u and l.coach_id = v_uid and l.revoked_at is null)) then
        raise exception 'SHARING_UNAVAILABLE' using errcode = '42501';
      end if;
    end if;
    if p_action = 'create_group' then
      if (select count(*) from private.titan_coach_groups where coach_id = v_uid) >= 20 then raise exception 'GROUP_LIMIT' using errcode = '22023'; end if;
      insert into private.titan_coach_groups (coach_id, title) values (v_uid, v_title) returning * into v_group;
    else
      select * into v_group from private.titan_coach_groups where id = v_id and coach_id = v_uid for update;
      if not found then raise exception 'GROUP_UNAVAILABLE' using errcode = '22023'; end if;
      if v_group.revision is distinct from (p_data->>'revision')::integer then raise exception 'COACH_CONFLICT'; end if;
      update private.titan_coach_groups set title = coalesce(v_title, title), revision = revision + 1, updated_at = now() where id = v_group.id returning * into v_group;
    end if;
    if v_links is not null then
      delete from private.titan_coach_group_members m using public.coach_links l where m.group_id = v_group.id and l.id = m.link_id and l.revoked_at is null and m.link_id <> all(v_links);
      insert into private.titan_coach_group_members (group_id, link_id) select v_group.id, u from unnest(v_links) u on conflict do nothing;
    end if;
    return jsonb_build_object('ok', true, 'id', v_group.id, 'revision', v_group.revision);
  end if;

  -- delete_group: the group, its members and its blocks go; every programme already received stays with its athlete, unchanged.
  if p_action = 'delete_group' then
    delete from private.titan_coach_groups where id = v_id and coach_id = v_uid returning * into v_group;
    if not found then raise exception 'GROUP_UNAVAILABLE' using errcode = '22023'; end if;
    return jsonb_build_object('ok', true, 'id', v_group.id);
  end if;

  -- prepare: a block for the group from a template of mine (its current version, frozen in the block), one recipient per current member.
  if p_action = 'prepare' then
    if not private.titan_flag_on('screens.coach_programs') then raise exception 'FEATURE_DISABLED' using errcode = '42501'; end if;
    begin select * into v_group from private.titan_coach_groups where id = nullif(p_data->>'group_id', '')::uuid and coach_id = v_uid for update;
    exception when others then raise exception 'INVALID_INPUT' using errcode = '22023'; end;
    if v_group.id is null then raise exception 'GROUP_UNAVAILABLE' using errcode = '22023'; end if;
    if (select count(*) from private.titan_coach_dispatches where group_id = v_group.id) >= 100 then raise exception 'DISPATCH_LIMIT' using errcode = '22023'; end if;
    begin select * into v_prog from private.titan_coach_programs where id = nullif(p_data->>'program_id', '')::uuid and coach_id = v_uid and archived_at is null;
    exception when others then raise exception 'INVALID_INPUT' using errcode = '22023'; end;
    if v_prog.id is null then raise exception 'PROGRAM_UNAVAILABLE' using errcode = '22023'; end if;
    select * into v_pv from private.titan_coach_program_versions where program_id = v_prog.id and version = v_prog.version;
    begin v_date := coalesce(nullif(p_data->>'start_date', '')::date, date_trunc('week', v_today)::date + 7);
    exception when others then raise exception 'INVALID_PERIOD' using errcode = '22023'; end;
    if extract(isodow from v_date) <> 1 or v_date < date_trunc('week', v_today)::date or v_date > v_today + 366 then raise exception 'INVALID_PERIOD' using errcode = '22023'; end if;
    if not exists (select 1 from private.titan_coach_group_members m join public.coach_links l on l.id = m.link_id where m.group_id = v_group.id and l.revoked_at is null) then
      raise exception 'GROUP_EMPTY' using errcode = '22023';
    end if;
    insert into private.titan_coach_dispatches (group_id, coach_id, program_id, program_version, title, goals, weeks, sessions, start_date)
      values (v_group.id, v_uid, v_prog.id, v_prog.version, v_prog.title, v_pv.goals, v_pv.weeks, v_pv.sessions, v_date) returning * into v_d;
    insert into private.titan_coach_dispatch_recipients (dispatch_id, link_id)
      select v_d.id, m.link_id from private.titan_coach_group_members m join public.coach_links l on l.id = m.link_id where m.group_id = v_group.id and l.revoked_at is null;
    return jsonb_build_object('ok', true, 'dispatch', private.titan_coach_dispatch_row(v_d, true));
  end if;

  select * into v_d from private.titan_coach_dispatches where id = v_id and coach_id = v_uid for update;
  if not found then raise exception 'DISPATCH_UNAVAILABLE' using errcode = '22023'; end if;

  -- variant: one athlete's version (or their exclusion from this block), on the block's revision read by the coach.
  if p_action = 'variant' then
    if v_d.revision is distinct from (p_data->>'revision')::integer then raise exception 'COACH_CONFLICT'; end if;
    select * into r from private.titan_coach_dispatch_recipients where dispatch_id = v_d.id and link_id = nullif(p_data->>'link_id', '')::uuid for update;
    if not found then raise exception 'RECIPIENT_UNAVAILABLE' using errcode = '22023'; end if;
    if r.status = 'sent' then raise exception 'ALREADY_SENT' using errcode = '22023'; end if;
    v_v := coalesce(p_data->'variant', r.variant);
    perform private.titan_coach_group_variant(v_d.sessions, v_v, v_d.weeks);
    update private.titan_coach_dispatch_recipients set variant = jsonb_strip_nulls(v_v), excluded = coalesce((p_data->>'excluded')::boolean, excluded)
     where dispatch_id = v_d.id and link_id = r.link_id;
    update private.titan_coach_dispatches set revision = revision + 1, updated_at = now() where id = v_d.id returning * into v_d;
    return jsonb_build_object('ok', true, 'dispatch', private.titan_coach_dispatch_row(v_d, true));
  end if;

  if p_action = 'discard' then
    if v_d.first_sent_at is not null then raise exception 'ALREADY_SENT' using errcode = '22023'; end if;
    delete from private.titan_coach_dispatches where id = v_d.id;
    return jsonb_build_object('ok', true, 'id', v_d.id);
  end if;

  -- send: every recipient not yet served and not excluded, each in its own sub-transaction, on the preview the coach read. A replayed op_id
  -- returns its results and writes nothing; a new send serves only what remains (a recipient already sent is never sent again).
  if p_action = 'send' then
    if not private.titan_flag_on('screens.coach_programs') then raise exception 'FEATURE_DISABLED' using errcode = '42501'; end if;
    begin v_op := (p_data->>'op_id')::uuid; exception when others then raise exception 'INVALID_INPUT' using errcode = '22023'; end;
    if v_op is null then raise exception 'INVALID_INPUT' using errcode = '22023'; end if;
    select jsonb_build_object('ok', true, 'already', true, 'results', s.results) into v_row from private.titan_coach_dispatch_sends s where s.dispatch_id = v_d.id and s.op_id = v_op;
    if v_row is not null then return v_row || jsonb_build_object('dispatch', private.titan_coach_dispatch_row(v_d, false)); end if;
    if (private.titan_coach_dispatch_row(v_d, false))->>'preview_key' is distinct from p_data->>'preview_key' then raise exception 'COACH_CONFLICT'; end if;
    for r in select x.* from private.titan_coach_dispatch_recipients x where x.dispatch_id = v_d.id and x.status <> 'sent' and not x.excluded order by x.link_id loop
      v_err := null; v_plan := null;
      begin
        -- Lock order of the portal: the sharing link first, then the programme and its proposals.
        select * into v_link from public.coach_links where id = r.link_id and coach_id = v_uid for update;
        if not found or v_link.revoked_at is not null then raise exception 'SHARING_UNAVAILABLE' using errcode = '42501'; end if;
        if not private.titan_coach_link_active(v_link.id) then raise exception 'COACH_CAPACITY_PAUSED' using errcode = '42501'; end if;
        v_v := private.titan_coach_group_variant(v_d.sessions, r.variant, v_d.weeks);
        v_start := v_d.start_date + 7 * (v_v->>'shift_weeks')::integer;
        if exists (select 1 from jsonb_array_elements(v_v->'sessions') e
                    where v_start + ((e->>'week')::integer - 1) * 7 + (e->>'day')::integer - 1 not between v_today and v_today + 366) then
          raise exception 'INVALID_PERIOD' using errcode = '22023';
        end if;
        if (select count(*) from private.titan_coach_plans where link_id = v_link.id and state <> 'discarded') >= 50 then raise exception 'PLAN_LIMIT' using errcode = '22023'; end if;
        if (select count(*) from public.coach_assignments where link_id = v_link.id) + jsonb_array_length(v_v->'sessions') > 500 then raise exception 'ASSIGNMENT_LIMIT' using errcode = '22023'; end if;
        -- The V1.9.4 send, for this athlete: a programme from the template (basis = the template version), sent at once, its sessions proposed.
        insert into private.titan_coach_plans (link_id, coach_id, program_id, program_version, basis, title, goals, start_date, weeks, sessions, state, sent_at, version, revision)
          values (v_link.id, v_uid, v_d.program_id, v_d.program_version,
                  jsonb_build_object('kind', 'program', 'id', v_d.program_id, 'version', v_d.program_version, 'title', v_d.title, 'weeks', v_d.weeks, 'goals', v_d.goals,
                                     'sessions', v_d.sessions, 'dispatch', v_d.id, 'variant', r.variant),
                  v_d.title, v_d.goals, v_start, v_d.weeks, v_v->'sessions', 'sent', now(), 1, 2)
          returning * into v_plan;
        insert into public.coach_assignments (link_id, title, sport, planned_date, instructions, plan_id, plan_key, plan_week)
          select v_link.id, e->>'title', e->>'sport', v_start + ((e->>'week')::integer - 1) * 7 + (e->>'day')::integer - 1, coalesce(e->>'instructions', ''),
                 v_plan.id, e->>'key', (e->>'week')::integer
            from jsonb_array_elements(v_v->'sessions') e;
        update public.coach_assignments set history = private.titan_coach_history_cap(history || jsonb_build_array(jsonb_build_object('k', 'from_plan', 'at', now(), 'plan', v_plan.title, 'week', plan_week, 'weeks', v_plan.weeks)))
         where plan_id = v_plan.id;
        insert into private.titan_coach_plan_versions (plan_id, version, kind, summary, snapshot, actor)
          values (v_plan.id, 1, 'sent', jsonb_build_object('sessions', jsonb_array_length(v_v->'sessions'), 'start_date', v_start, 'weeks', v_d.weeks,
                    'changes', jsonb_array_length(v_v->'changes'), 'group', true),
                  private.titan_coach_plan_snapshot(v_plan.id), v_uid);
        update private.titan_coach_dispatch_recipients set status = 'sent', error = null, sent_at = now(), plan_id = v_plan.id, attempts = attempts + 1, last_attempt_at = now()
         where dispatch_id = v_d.id and link_id = r.link_id;
      exception when others then
        get stacked diagnostics v_err = message_text;
        v_err := case when v_err ~ '^[A-Z_]{3,40}$' then v_err else 'SEND_ERROR' end;
        v_plan := null;
        update private.titan_coach_dispatch_recipients set status = 'failed', error = v_err, attempts = attempts + 1, last_attempt_at = now()
         where dispatch_id = v_d.id and link_id = r.link_id;
      end;
      select username into v_name from public.profiles p join public.coach_links l on l.athlete_id = p.id where l.id = r.link_id and l.revoked_at is null;
      v_results := v_results || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object('link_id', r.link_id, 'name', v_name,
        'status', case when v_err is null then 'sent' else 'failed' end, 'error', v_err, 'plan_id', v_plan.id, 'sessions', case when v_err is null then jsonb_array_length(v_v->'sessions') else null end)));
    end loop;
    update private.titan_coach_dispatches set first_sent_at = coalesce(first_sent_at, now()), updated_at = now(), revision = revision + 1,
        completed_at = case when exists (select 1 from private.titan_coach_dispatch_recipients x where x.dispatch_id = v_d.id and x.status <> 'sent' and not x.excluded) then null else coalesce(completed_at, now()) end
     where id = v_d.id returning * into v_d;
    insert into private.titan_coach_dispatch_sends (dispatch_id, op_id, results) values (v_d.id, v_op, v_results);
    return jsonb_build_object('ok', true, 'already', false, 'results', v_results, 'dispatch', private.titan_coach_dispatch_row(v_d, false));
  end if;
  raise exception 'INVALID_ACTION' using errcode = '22023';
end;
$function$;
revoke all on function public.titan_coach_group_v1(text, jsonb) from public, anon;
grant execute on function public.titan_coach_group_v1(text, jsonb) to authenticated;

-- ---- The export: the body of 20261205090000, plus the coach's groups and blocks (their own organisation: titles, members as link ids,
-- the template and variant of each recipient, the outcomes). Nothing of it concerns or reaches an athlete.
create or replace function private.titan_export_extras_v1(p_uid uuid)
returns jsonb language sql stable security definer set search_path = '' as $$
  select private.titan_export_extras_before_cadence_v1(p_uid) || jsonb_build_object(
    'cadenceWeekClaims', coalesce((
      select jsonb_agg(jsonb_build_object('week', c.week_start, 'days', c.days, 'target', c.target, 'credits', c.credits, 'claimed_at', c.claimed_at) order by c.week_start)
      from private.titan_cadence_claims c where c.user_id = p_uid), '[]'::jsonb),
    'timeCapsules', coalesce((
      select jsonb_agg(jsonb_build_object('message', t.message, 'months', t.months, 'deliver_on', t.deliver_on, 'written_minutes', t.written_minutes,
        'written_days', t.written_days, 'created_at', t.created_at, 'opened_at', t.opened_at) order by t.created_at)
      from private.titan_time_capsules t where t.user_id = p_uid), '[]'::jsonb),
    'lifeChapters', coalesce((
      select jsonb_agg(jsonb_build_object('title', l.title, 'starts_on', l.starts_on, 'ends_on', l.ends_on, 'created_at', l.created_at) order by l.starts_on)
      from private.titan_life_chapters l where l.user_id = p_uid), '[]'::jsonb),
    'coachFeedback', coalesce((
      select jsonb_agg(jsonb_build_object('link_id', f.link_id, 'assignment_id', f.assignment_id, 'message_id', f.message_id, 'session_day', f.session_day,
        'adjustment', f.adjustment, 'adjustment_state', f.adjustment_state, 'answered_at', f.answered_at, 'read_at', f.read_at, 'created_at', f.created_at) order by f.created_at)
      from private.titan_coach_feedback f join public.coach_links l on l.id = f.link_id where p_uid in (l.coach_id, l.athlete_id)), '[]'::jsonb),
    'coachReviewDrafts', coalesce((
      select jsonb_agg(jsonb_build_object('link_id', d.link_id, 'week', d.week_start, 'state', d.state, 'basis', d.basis - 'base', 'content', d.content,
        'assignment_id', d.assignment_id, 'created_at', d.created_at, 'sent_at', d.sent_at) order by d.created_at)
      from private.titan_coach_review_drafts d where d.coach_id = p_uid), '[]'::jsonb),
    'coachPrograms', coalesce((
      select jsonb_agg(jsonb_build_object('title', g.title, 'version', g.version, 'archived_at', g.archived_at, 'created_at', g.created_at,
        'versions', (select jsonb_agg(jsonb_build_object('version', v.version, 'weeks', v.weeks, 'goals', v.goals, 'sessions', v.sessions, 'created_at', v.created_at) order by v.version)
                       from private.titan_coach_program_versions v where v.program_id = g.id)) order by g.created_at)
      from private.titan_coach_programs g where g.coach_id = p_uid), '[]'::jsonb),
    'coachPlans', coalesce((
      select jsonb_agg(jsonb_build_object('link_id', p.link_id, 'title', p.title, 'goals', p.goals, 'start_date', p.start_date, 'weeks', p.weeks, 'state', p.state,
        'sessions', case when p.coach_id = p_uid or p.state in ('sent', 'closed') then p.sessions else null end, 'created_at', p.created_at, 'sent_at', p.sent_at, 'closed_at', p.closed_at,
        'versions', (select jsonb_agg(jsonb_build_object('version', v.version, 'kind', v.kind, 'scope', v.scope, 'summary', v.summary, 'snapshot', v.snapshot, 'created_at', v.created_at) order by v.version)
                       from private.titan_coach_plan_versions v where v.plan_id = p.id)) order by p.created_at)
      from private.titan_coach_plans p join public.coach_links l on l.id = p.link_id
     where p.coach_id = p_uid or (l.athlete_id = p_uid and p.state in ('sent', 'closed'))), '[]'::jsonb),
    'coachCycleReports', coalesce((
      select jsonb_agg(jsonb_strip_nulls(jsonb_build_object('link_id', r.link_id, 'cycle', p.title, 'start_date', p.start_date, 'weeks', p.weeks, 'version', r.version,
        'state', case when r.coach_id = p_uid or r.state <> 'draft' then r.state else 'published' end,
        'working_copy', case when r.coach_id = p_uid then r.content else null end,
        'published', case when l.athlete_id = p_uid or (l.revoked_at is null and r.withdrawn_at is null and private.titan_coach_link_active(l.id)
                               and (select v.contract from private.titan_coach_cycle_report_versions v where v.report_id = r.id and v.version = r.version) = private.titan_coach_cycle_contract(l))
                          then private.titan_coach_cycle_published(r, p, l) else null end,
        'withdrawn_at', r.withdrawn_at, 'created_at', r.created_at, 'published_at', r.published_at,
        'exports', case when l.athlete_id = p_uid then (select jsonb_agg(jsonb_build_object('role', x.role, 'version', x.version, 'at', x.created_at, 'fields', x.fields) order by x.created_at)
                                                         from private.titan_coach_cycle_report_exports x where x.report_id = r.id) else null end)) order by r.created_at)
      from private.titan_coach_cycle_reports r join private.titan_coach_plans p on p.id = r.plan_id join public.coach_links l on l.id = r.link_id
     where r.coach_id = p_uid or (l.athlete_id = p_uid and (r.state = 'proposed' or r.version >= 1))), '[]'::jsonb),
    'coachGroups', coalesce((
      select jsonb_agg(jsonb_build_object('title', g.title, 'created_at', g.created_at, 'updated_at', g.updated_at,
        'members', (select coalesce(jsonb_agg(jsonb_build_object('link_id', m.link_id, 'added_at', m.added_at) order by m.added_at), '[]'::jsonb) from private.titan_coach_group_members m where m.group_id = g.id),
        'dispatches', (select coalesce(jsonb_agg(jsonb_build_object('title', d.title, 'start_date', d.start_date, 'weeks', d.weeks, 'program_version', d.program_version,
            'created_at', d.created_at, 'first_sent_at', d.first_sent_at, 'completed_at', d.completed_at,
            'recipients', (select coalesce(jsonb_agg(jsonb_build_object('link_id', x.link_id, 'variant', x.variant, 'excluded', x.excluded, 'status', x.status, 'error', x.error,
                             'attempts', x.attempts, 'sent_at', x.sent_at) order by x.link_id), '[]'::jsonb) from private.titan_coach_dispatch_recipients x where x.dispatch_id = d.id))
            order by d.created_at), '[]'::jsonb) from private.titan_coach_dispatches d where d.group_id = g.id)) order by g.created_at)
      from private.titan_coach_groups g where g.coach_id = p_uid), '[]'::jsonb));
$$;
revoke all on function private.titan_export_extras_v1(uuid) from public, anon, authenticated;

-- Measure (team only, no identifier): groups and their size, blocks, recipients by outcome and refusals by reason, resumptions, the
-- recipients with an individual version (and those whose sent version really differs from the template), the preparation time of a block
-- (prepared → first send) against the time of the individual V1.9.4 programmes (draft → sent), so the time saved can be read on a week.
create or replace function private.titan_coach_group_measure()
returns jsonb language sql stable security definer set search_path = ''
as $function$
  select jsonb_build_object(
    'groups', (select count(*) from private.titan_coach_groups),
    'membersMedian', (select percentile_cont(0.5) within group (order by n) from (select count(*) n from private.titan_coach_group_members group by group_id) x),
    'dispatches', (select count(*) from private.titan_coach_dispatches),
    'dispatchesComplete', (select count(*) from private.titan_coach_dispatches where completed_at is not null),
    'recipients', (select coalesce(jsonb_object_agg(s, n), '{}'::jsonb) from (select case when excluded then 'excluded' else status end s, count(*) n from private.titan_coach_dispatch_recipients group by 1) x),
    'refusals', (select coalesce(jsonb_object_agg(e, n), '{}'::jsonb) from (select r->>'error' e, count(*) n from private.titan_coach_dispatch_sends s, jsonb_array_elements(s.results) r
                   where r ? 'error' group by 1) x),
    'refusedNow', (select coalesce(jsonb_object_agg(e, n), '{}'::jsonb) from (select error e, count(*) n from private.titan_coach_dispatch_recipients where error is not null and not excluded group by 1) x),
    'sends', (select count(*) from private.titan_coach_dispatch_sends),
    'resumed', (select count(*) from private.titan_coach_dispatch_recipients where status = 'sent' and attempts > 1),
    'individual', (select count(*) from private.titan_coach_dispatch_recipients where variant <> '{}'::jsonb and not excluded),
    'individualSent', (select count(*) from private.titan_coach_dispatch_recipients x join private.titan_coach_plans p on p.id = x.plan_id
                         where jsonb_array_length(private.titan_coach_plan_changes(p.basis->'sessions', p.sessions)) > 0 or p.start_date <> (select d.start_date from private.titan_coach_dispatches d where d.id = x.dispatch_id)),
    'duplicatePlans', (select count(*) from (select p.basis->>'dispatch', p.link_id from private.titan_coach_plans p where p.basis ? 'dispatch' and p.state <> 'discarded'
                         group by 1, 2 having count(*) > 1) q),
    'prepMinutesMedian', (select round((percentile_cont(0.5) within group (order by extract(epoch from first_sent_at - created_at) / 60.0))::numeric, 1)
                            from private.titan_coach_dispatches where first_sent_at is not null),
    'programsSentPerBlock', (select round(avg(n)::numeric, 1) from (select count(*) n from private.titan_coach_dispatch_recipients where status = 'sent' group by dispatch_id) x),
    'individualPrepMinutesMedian', (select round((percentile_cont(0.5) within group (order by extract(epoch from sent_at - created_at) / 60.0))::numeric, 1)
                            from private.titan_coach_plans where sent_at is not null and basis->>'dispatch' is null))
$function$;
revoke all on function private.titan_coach_group_measure() from public, anon, authenticated;

